package com.trampolim.api.privacy;

import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

/** One instance per trail; only request metadata, never passwords, documents or free-text diagnoses. */
public class PrivacyStore {
 public final String trail; private final JdbcTemplate db; private final TransactionTemplate tx; private final String accounts;
 private static final String FIELDS="id,state,basis_code,review_after,revision,created_at,updated_at";
 public PrivacyStore(String trail,JdbcTemplate db,PlatformTransactionManager manager){this.trail=trail;this.db=db;tx=new TransactionTemplate(manager);accounts=switch(trail){case "oportunidades"->"app_users";case "empresas"->"company_users";case "capacita"->"student_users";default->throw new IllegalArgumentException();};}
 private long user(String email,boolean lock){if(email==null||email.isBlank())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);var rows=db.queryForList("SELECT id FROM "+accounts+" WHERE LOWER(email)=LOWER(?)"+(trail.equals("oportunidades")?" AND account_type='PERSON'":" AND account_status='ACTIVE'")+(lock?" FOR UPDATE":""),email);if(rows.size()!=1)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return ((Number)rows.getFirst().get("id")).longValue();}
 public void recordExport(String email){db.update("INSERT INTO privacy_export_audit(user_id,event) VALUES (?,'EXPORT_REQUESTED')",user(email,false));}
 public List<Map<String,Object>> list(String email,int page){page(page);return db.queryForList("SELECT "+FIELDS+" FROM privacy_requests WHERE user_id=? ORDER BY created_at DESC,id LIMIT 50 OFFSET ?",user(email,false),page*50);}
 public Map<String,Object> request(String email,UUID clientKey,boolean confirmed){if(clientKey==null||!confirmed)bad("Confirme a solicitação. Nenhum dado será apagado automaticamente.");return tx.execute(status->{long uid=user(email,true);var previous=db.queryForList("SELECT "+FIELDS+" FROM privacy_requests WHERE user_id=? AND client_key=?",uid,clientKey);if(!previous.isEmpty())return previous.getFirst();var active=db.queryForList("SELECT "+FIELDS+" FROM privacy_requests WHERE user_id=? AND state IN ('OPEN','REVIEWING','READY','RETAINED')",uid);if(!active.isEmpty())return active.getFirst();if(db.queryForObject("SELECT count(*) FROM privacy_requests WHERE user_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Long.class,uid)>=10)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS);UUID id=UUID.randomUUID();db.update("INSERT INTO privacy_requests(id,user_id,client_key) VALUES (?,?,?)",id,uid,clientKey);audit(id,"holder:"+uid,"REQUESTED",null,"OPEN","USER_REQUEST");return own(uid,id);});}
 private Map<String,Object> own(long uid,UUID id){return db.queryForList("SELECT "+FIELDS+" FROM privacy_requests WHERE id=? AND user_id=?",id,uid).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 public Map<String,Object> cancel(String email,UUID id,long expected){return tx.execute(status->{long uid=user(email,true);var row=own(uid,id);if(((Number)row.get("revision")).longValue()!=expected)conflict();if(!Set.of("OPEN","READY").contains(row.get("state")))throw new ResponseStatusException(HttpStatus.CONFLICT,"A solicitação em análise ou retenção precisa ser revisada pela administração.");db.update("UPDATE privacy_requests SET state='CANCELLED',case_reference=NULL,review_after=NULL,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",id);audit(id,"holder:"+uid,"CANCELLED",row.get("state").toString(),"CANCELLED",row.get("basis_code").toString());return own(uid,id);});}
 public List<Map<String,Object>> queue(int page){page(page);return db.queryForList("SELECT "+FIELDS+",user_id FROM privacy_requests WHERE state IN ('OPEN','REVIEWING','READY','RETAINED') ORDER BY created_at,id LIMIT 50 OFFSET ?",page*50);}
 public record Review(String state,String basisCode,String caseReference,Instant reviewAfter,long expectedRevision){}
 public Map<String,Object> review(UUID id,Review input,String actor){if(input==null||!Set.of("REVIEWING","READY","RETAINED").contains(Objects.toString(input.state(),""))||!Set.of("USER_REQUEST","ORGANIZATION_RESPONSIBILITY","RETENTION_REVIEW","SECURITY_REVIEW").contains(Objects.toString(input.basisCode(),""))||input.caseReference()==null||!input.caseReference().matches("[A-Za-z0-9_-]{3,80}"))bad("Informe decisão, motivo e referência interna sem dados pessoais.");if(input.state().equals("RETAINED")&&(input.basisCode().equals("USER_REQUEST")||input.reviewAfter()==null||!input.reviewAfter().isAfter(Instant.now())||input.reviewAfter().isAfter(Instant.now().plus(Duration.ofDays(90)))))bad("Defina motivo e reavaliação em até 90 dias; isso não estabelece prazo legal.");return tx.execute(status->{var subject=db.queryForList("SELECT user_id FROM privacy_requests WHERE id=?",id);if(subject.isEmpty()||subject.getFirst().get("user_id")==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);long uid=((Number)subject.getFirst().get("user_id")).longValue();db.queryForList("SELECT id FROM "+accounts+" WHERE id=? FOR UPDATE",uid);var row=db.queryForList("SELECT * FROM privacy_requests WHERE id=? FOR UPDATE",id).getFirst();if(((Number)row.get("revision")).longValue()!=input.expectedRevision())conflict();if(Set.of("CANCELLED","COMPLETED").contains(row.get("state")))conflict();db.update("UPDATE privacy_requests SET state=?,basis_code=?,case_reference=?,review_after=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.state(),input.basisCode(),input.caseReference(),input.state().equals("RETAINED")?java.sql.Timestamp.from(input.reviewAfter()):null,id);audit(id,actor,"REVIEWED",row.get("state").toString(),input.state(),input.basisCode());return own(uid,id);});}
 public Map<String,Object> disposalPreview(int days){if(days<30||days>3650)bad("Informe uma janela técnica entre 30 e 3650 dias; ela não define obrigação legal.");long closed=db.queryForObject("SELECT count(*) FROM privacy_requests WHERE state IN ('CANCELLED','COMPLETED') AND updated_at<CURRENT_TIMESTAMP-make_interval(days=>?)",Long.class,days);long exports=db.queryForObject("SELECT count(*) FROM privacy_export_audit WHERE created_at<CURRENT_TIMESTAMP-make_interval(days=>?)",Long.class,days);return Map.of("trail",trail,"ageDays",days,"closedRequestCandidates",closed,"exportAuditCandidates",exports,"automaticDisposal",false,"reviewRequired",true);}
 public List<Map<String,Object>> audit(UUID request,int page){page(page);return db.queryForList("SELECT id,actor_ref,event,from_state,to_state,basis_code,created_at FROM privacy_audit WHERE request_id=? ORDER BY id DESC LIMIT 50 OFFSET ?",request,page*50);}
 private void audit(UUID id,String actor,String event,String from,String to,String basis){db.update("INSERT INTO privacy_audit(request_id,actor_ref,event,from_state,to_state,basis_code) VALUES (?,?,?,?,?,?)",id,actor,event,from,to,basis);}
 private static void page(int page){if(page<0||page>200)bad("Página inválida.");}
 private static void bad(String reason){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,reason);}
 private static void conflict(){throw new ResponseStatusException(HttpStatus.CONFLICT,"O estado mudou. Atualize a solicitação antes de continuar.");}
}
